import{_ as l,a0 as p,w as o,s as r,I as t,x as e,a1 as a,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 Git 工作树对你的代码进行自由实验 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Git 工作树对你的代码进行自由实验 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Git 工作树对你的代码进行自由实验 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Git 工作树对你的代码进行自由实验 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210406 Experiment on your code freely with Git worktree","title":"使用 Git 工作树对你的代码进行自由实验","tag":"202104","desc":""},"relativePath":"202104/20210406 Experiment on your code freely with Git worktree.md","filePath":"[post].md"}'),h={name:"202104/20210406 Experiment on your code freely with Git worktree.md"};function g(k,s,c,u,b,f){const i=p("Link");return o(),r("div",null,[s[22]||(s[22]=t("h1",{id:"使用-git-工作树对你的代码进行自由实验",tabindex:"-1"},[e("使用 Git 工作树对你的代码进行自由实验 "),t("a",{class:"header-anchor",href:"#使用-git-工作树对你的代码进行自由实验","aria-label":"Permalink to “使用 Git 工作树对你的代码进行自由实验”"},"​")],-1)),s[23]||(s[23]=t("blockquote",null,[t("p",null,"获得自由尝试的权利，同时在你的实验出错时可以安全地拥有一个新的、链接的克隆存储库。")],-1)),s[24]||(s[24]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/16/085512x3auafu5uaymk52u.jpg",alt:""})],-1)),s[25]||(s[25]=t("p",null,"Git 的设计部分是为了进行实验。如果你知道你的工作会被安全地跟踪，并且在出现严重错误时有安全状态存在，你就不会害怕尝试新的想法。不过，创新的部分代价是，你很可能会在这个过程中弄得一团糟。文件会被重新命名、移动、删除、更改、切割成碎片；新的文件被引入；你不打算跟踪的临时文件会在你的工作目录中占据一席之地等等。",-1)),t("p",null,[s[1]||(s[1]=e("简而言之，你的工作空间变成了纸牌屋，在“快好了！”和“哦，不，我做了什么？”之间岌岌可危地平衡着。那么，当你需要把仓库恢复到下午的一个已知状态，以便完成一些真正的工作时，该怎么办？我立刻想到了 ",-1)),s[2]||(s[2]=t("code",null,"git branch",-1)),s[3]||(s[3]=e(" 和 ",-1)),a(i,{href:"https://linux.cn/article-13293-1.html"},{default:n(()=>[...s[0]||(s[0]=[e("git stash",-1)])]),_:1}),s[4]||(s[4]=e(" 这两个经典命令，但这两个命令都不是用来处理未被跟踪的文件的，而且文件路径的改变和其他重大的转变也会让人困惑，它们只能把工作暂存（",-1)),s[5]||(s[5]=t("code",null,"stash",-1)),s[6]||(s[6]=e("）起来以备后用。解决这个需求的答案是 Git 工作树。",-1))]),s[26]||(s[26]=d(`<h3 id="什么是-git-工作树" tabindex="-1">什么是 Git 工作树 <a class="header-anchor" href="#什么是-git-工作树" aria-label="Permalink to “什么是 Git 工作树”">​</a></h3><p>Git <ruby>工作树<rt>worktree</rt></ruby>是 Git 仓库的一个链接副本，允许你同时签出多个分支。工作树与主工作副本的路径是分开的，它可以处于不同的状态和不同的分支上。在 Git 中新建工作树的好处是，你可以在不干扰当前工作环境的情况下，做出与当前任务无关的修改、提交修改，然后在以后合并。</p><p>直接从 <code>git-worktree</code> 手册中找到了一个典型的例子：当你正在为一个项目做一个令人兴奋的新功能时，你的项目经理告诉你有一个紧急的修复工作。问题是你的工作仓库（你的“工作树”）处于混乱状态，因为你正在开发一个重要的新功能。你不想在当前的冲刺中“偷偷地”进行修复，而且你也不愿意把变更暂存起来，为修复创建一个新的分支。相反，你决定创建一个新的工作树，这样你就可以在那里进行修复：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch | tee</span></span>
<span class="line"><span>* dev</span></span>
<span class="line"><span>trunk</span></span>
<span class="line"><span>$ git worktree add -b hotfix ~/code/hotfix trunk</span></span>
<span class="line"><span>Preparing ../hotfix (identifier hotfix)</span></span>
<span class="line"><span>HEAD is now at 62a2daf commit</span></span></code></pre></div><p>在你的 <code>code</code> 目录中，你现在有一个新的目录叫做 <code>hotfix</code>，它是一个与你的主项目仓库相连的 Git 工作树，它的 <code>HEAD</code> 停在叫做 <code>trunk</code> 的分支上。现在你可以把这个工作树当作你的主工作区来对待。你可以把目录切换到它里面，进行紧急修复、提交、并最终删除这个工作树：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/code/hotfix</span></span>
<span class="line"><span>$ sed -i &#39;s/teh/the/&#39; hello.txt</span></span>
<span class="line"><span>$ git commit --all --message &#39;urgent hot fix&#39;</span></span></code></pre></div><p>一旦你完成了你的紧急工作，你就可以回到你之前的任务。你可以控制你的热修复何时被集成到主项目中。例如，你可以直接将变更从其工作树推送到项目的远程存储库中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push origin HEAD</span></span>
<span class="line"><span>$ cd ~/code/myproject</span></span></code></pre></div><p>或者你可以将工作树存档为 TAR 或 ZIP 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/code/myproject</span></span>
<span class="line"><span>$ git archive --format tar --output hotfix.tar master</span></span></code></pre></div><p>或者你可以从单独的工作树中获取本地的变化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/code/hotfix     09e585d [master]</span></span></code></pre></div><p>从那里，你可以使用任何最适合你和你的团队的策略合并你的变化。</p><h3 id="列出活动工作树" tabindex="-1">列出活动工作树 <a class="header-anchor" href="#列出活动工作树" aria-label="Permalink to “列出活动工作树”">​</a></h3><p>你可以使用 <code>git worktree list</code> 命令获得工作树的列表，并查看每个工作树签出的分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/code/hotfix     09e585d [master]</span></span></code></pre></div><p>你可以在任何一个工作树中使用这个功能。工作树始终是连接的（除非你手动移动它们，破坏 Git 定位工作树的能力，从而切断连接）。</p><h3 id="移动工作树" tabindex="-1">移动工作树 <a class="header-anchor" href="#移动工作树" aria-label="Permalink to “移动工作树”">​</a></h3><p>Git 会跟踪项目 <code>.git</code> 目录下工作树的位置和状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/code/myproject/.git/worktrees/hotfix/gitdir</span></span>
<span class="line"><span>/home/seth/code/hotfix/.git</span></span></code></pre></div><p>如果你需要重定位一个工作树，必须使用 <code>git worktree move</code>；否则，当 Git 试图更新工作树的状态时，就会失败：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/Temp</span></span>
<span class="line"><span>$ git worktree move hotfix ~/Temp</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span>
<span class="line"><span>/home/seth/Temp/hotfix     09e585d [master]</span></span></code></pre></div><h3 id="移除工作树" tabindex="-1">移除工作树 <a class="header-anchor" href="#移除工作树" aria-label="Permalink to “移除工作树”">​</a></h3><p>当你完成你的工作时，你可以用 <code>remove</code> 子命令删除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree remove hotfix</span></span>
<span class="line"><span>$ git worktree list</span></span>
<span class="line"><span>/home/seth/code/myproject  15fca84 [dev]</span></span></code></pre></div><p>为了确保你的 <code>.git</code> 目录是干净的，在删除工作树后使用 <code>prune</code> 子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git worktree remove prune</span></span></code></pre></div><h3 id="何时使用工作树" tabindex="-1">何时使用工作树 <a class="header-anchor" href="#何时使用工作树" aria-label="Permalink to “何时使用工作树”">​</a></h3><p>与许多选项一样，无论是标签还是书签还是自动备份，都要靠你来跟踪你产生的数据，否则可能会变得不堪重负。不要经常使用工作树，要不你最终会有 20 份存储库的副本，每份副本的状态都略有不同。我发现最好是创建一个工作树，做需要它的任务，提交工作，然后删除树。保持简单和专注。</p><p>重要的是，工作树为你管理 Git 存储库的方式提供了更好的灵活性。在需要的时候使用它们，再也不用为了检查另一个分支上的内容而争先恐后地保存工作状态了。</p><hr>`,31)),t("p",null,[s[8]||(s[8]=e("via: ",-1)),a(i,{href:"https://opensource.com/article/21/4/git-worktree"},{default:n(()=>[...s[7]||(s[7]=[e("https://opensource.com/article/21/4/git-worktree",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=e("作者：",-1)),a(i,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[9]||(s[9]=[e("Seth Kenlon",-1)])]),_:1}),s[14]||(s[14]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 译者：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1}),s[16]||(s[16]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[18]||(s[18]=[e("Linux中国",-1)])]),_:1}),s[21]||(s[21]=e(" 荣誉推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
